              "operation": "用 pandas/openpyxl 读取 xlsx 或 csv，识别日期/摘要/收入/支出/余额列，遍历全部数据行而非抽样",
              "output_refs": ["transactions"],
              "postconditions": ["每条记录含日期、摘要、收入、支出至少四项"],
              "asset_ids": [],
              "evidence_refs": [
                {
                  "source_id": "conv_f74f7410ccfd",
